az6(a,b){return"\u0648\u062c\u0647\u0627\u064b \u0644\u0648\u062c\u0647: "+a+" \u0648"+b+"!"},
az7(a,b){return"\u0627\u0644\u064a\u0648\u0645 \u0639\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0645\u0644\u0639\u0628 "+a+" \u0648"+b+"!"},
